// Collect all metric sources
const tradeData = $('HTTP: Fetch Trade Metrics (24h)').first()?.json || {};
const pnlHistory = $('HTTP: Fetch P&L Rolling Average').first()?.json || {};
const agentLatency = $('HTTP: Fetch Agent Response Times').first()?.json || {};
const errorRates = $('HTTP: Fetch Error Rate Trends').first()?.json || {};
const apiLatency = $('HTTP: Fetch API Latency Stats').first()?.json || {};
const baselines = $('HTTP: Fetch Historical Baselines').first()?.json || {};

const now = new Date();
const anomalies = [];

// Helper: Calculate Z-score
function zScore(value, mean, stdDev) {
  if (stdDev === 0 || isNaN(stdDev)) return 0;
  return (value - mean) / stdDev;
}

// Helper: Calculate mean and std dev from array
function calcStats(arr) {
  if (!arr || arr.length === 0) return { mean: 0, stdDev: 0 };
  const mean = arr.reduce((a, b) => a + b, 0) / arr.length;
  const variance = arr.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / arr.length;
  return { mean, stdDev: Math.sqrt(variance) };
}

// Helper: Classify severity based on z-score
function classifySeverity(z) {
  const absZ = Math.abs(z);
  if (absZ >= 3) return 'critical';
  if (absZ >= 2.5) return 'high';
  if (absZ >= 2) return 'medium';
  return 'low';
}

// 1. Analyze Trade Frequency
const trades = tradeData.trades || [];
const recentHourTrades = trades.filter(t => {
  const tradeTime = new Date(t.entry_time || t.timestamp);
  return (now - tradeTime) < 60 * 60 * 1000; // Last hour
}).length;

const tradeFreqBaseline = baselines.tradeFrequency || { mean: 5, stdDev: 2 };
const tradeFreqZ = zScore(recentHourTrades, tradeFreqBaseline.mean, tradeFreqBaseline.stdDev);

if (Math.abs(tradeFreqZ) >= 2) {
  anomalies.push({
    type: 'trade_frequency',
    metric: 'trades_per_hour',
    currentValue: recentHourTrades,
    baseline: tradeFreqBaseline.mean,
    zScore: tradeFreqZ,
    severity: classifySeverity(tradeFreqZ),
    direction: tradeFreqZ > 0 ? 'high' : 'low',
    description: tradeFreqZ > 0 
      ? `Abnormally HIGH trade frequency: ${recentHourTrades} trades/hour (baseline: ${tradeFreqBaseline.mean.toFixed(1)})`
      : `Abnormally LOW trade frequency: ${recentHourTrades} trades/hour (baseline: ${tradeFreqBaseline.mean.toFixed(1)})`
  });
}

// 2. Analyze P&L Deviation
const todayPnL = trades.reduce((sum, t) => sum + (parseFloat(t.pnl) || 0), 0);
const pnlBaseline = baselines.dailyPnl || pnlHistory.baseline || { mean: 50, stdDev: 150 };
const pnlZ = zScore(todayPnL, pnlBaseline.mean, pnlBaseline.stdDev);

if (Math.abs(pnlZ) >= 2) {
  anomalies.push({
    type: 'pnl_deviation',
    metric: 'daily_pnl',
    currentValue: todayPnL,
    baseline: pnlBaseline.mean,
    zScore: pnlZ,
    severity: classifySeverity(pnlZ),
    direction: pnlZ > 0 ? 'high' : 'low',
    description: pnlZ > 0
      ? `Exceptional P&L: $${todayPnL.toFixed(2)} (${Math.abs(pnlZ).toFixed(1)} std devs above mean)`
      : `Significant loss: $${todayPnL.toFixed(2)} (${Math.abs(pnlZ).toFixed(1)} std devs below mean)`
  });
}

// 3. Analyze Agent Response Times
const agentLatencies = agentLatency.latencies || agentLatency.data || [];
if (agentLatencies.length > 0) {
  const currentAvgLatency = agentLatencies.reduce((s, l) => s + (l.avgMs || l.latency || 0), 0) / agentLatencies.length;
  const latencyBaseline = baselines.agentLatency || { mean: 100, stdDev: 30 };
  const latencyZ = zScore(currentAvgLatency, latencyBaseline.mean, latencyBaseline.stdDev);

  if (latencyZ >= 2) { // Only care about high latency
    anomalies.push({
      type: 'agent_latency',
      metric: 'avg_response_ms',
      currentValue: currentAvgLatency,
      baseline: latencyBaseline.mean,
      zScore: latencyZ,
      severity: classifySeverity(latencyZ),
      direction: 'high',
      description: `Agent response time elevated: ${currentAvgLatency.toFixed(0)}ms (baseline: ${latencyBaseline.mean.toFixed(0)}ms)`,
      affectedAgents: agentLatencies.filter(l => (l.avgMs || l.latency || 0) > latencyBaseline.mean + 2 * latencyBaseline.stdDev).map(l => l.name || l.agentId)
    });
  }
}

// 4. Analyze Error Rates
const errorData = errorRates.errors || errorRates.data || [];
const recentErrors = errorData.filter(e => {
  const errorTime = new Date(e.timestamp || e.time);
  return (now - errorTime) < 60 * 60 * 1000; // Last hour
}).length;

const errorBaseline = baselines.errorRate || { mean: 2, stdDev: 1.5 };
const errorZ = zScore(recentErrors, errorBaseline.mean, errorBaseline.stdDev);

if (errorZ >= 2) {
  anomalies.push({
    type: 'error_rate',
    metric: 'errors_per_hour',
    currentValue: recentErrors,
    baseline: errorBaseline.mean,
    zScore: errorZ,
    severity: classifySeverity(errorZ),
    direction: 'high',
    description: `Elevated error rate: ${recentErrors} errors/hour (baseline: ${errorBaseline.mean.toFixed(1)})`,
    recentErrors: errorData.slice(0, 5).map(e => ({ message: e.message, node: e.node || e.source }))
  });
}

// 5. Analyze API Latency Spikes
const apiLatencies = apiLatency.endpoints || apiLatency.data || [];
const spikingEndpoints = [];
apiLatencies.forEach(endpoint => {
  const latencyVal = endpoint.p95 || endpoint.avgMs || endpoint.latency || 0;
  const endpointBaseline = baselines.apiLatency?.[endpoint.path] || { mean: 200, stdDev: 50 };
  const endpointZ = zScore(latencyVal, endpointBaseline.mean, endpointBaseline.stdDev);

  if (endpointZ >= 2.5) {
    spikingEndpoints.push({
      path: endpoint.path || endpoint.name,
      latency: latencyVal,
      zScore: endpointZ,
      baseline: endpointBaseline.mean
    });
  }
});

if (spikingEndpoints.length > 0) {
  anomalies.push({
    type: 'api_latency_spike',
    metric: 'endpoint_p95_ms',
    currentValue: Math.max(...spikingEndpoints.map(e => e.latency)),
    baseline: 200,
    zScore: Math.max(...spikingEndpoints.map(e => e.zScore)),
    severity: classifySeverity(Math.max(...spikingEndpoints.map(e => e.zScore))),
    direction: 'high',
    description: `API latency spikes detected on ${spikingEndpoints.length} endpoint(s)`,
    affectedEndpoints: spikingEndpoints
  });
}

// 6. Detect consecutive losses (behavioral anomaly)
const recentTrades = trades.slice(0, 10); // Last 10 trades
let consecutiveLosses = 0;
for (const trade of recentTrades) {
  if ((parseFloat(trade.pnl) || 0) < 0) consecutiveLosses++;
  else break;
}

if (consecutiveLosses >= 4) {
  anomalies.push({
    type: 'consecutive_losses',
    metric: 'loss_streak',
    currentValue: consecutiveLosses,
    baseline: 2,
    zScore: consecutiveLosses / 2, // Rough z-score approximation
    severity: consecutiveLosses >= 6 ? 'critical' : 'high',
    direction: 'high',
    description: `LOSS STREAK: ${consecutiveLosses} consecutive losing trades detected`
  });
}

// Sort anomalies by severity
const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
anomalies.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

return {
  json: {
    timestamp: now.toISOString(),
    anomalyCount: anomalies.length,
    hasCritical: anomalies.some(a => a.severity === 'critical'),
    hasHigh: anomalies.some(a => a.severity === 'high'),
    anomalies,
    metricsSnapshot: {
      recentHourTrades,
      todayPnL,
      recentErrors,
      consecutiveLosses
    }
  }
};

const data = $input.first().json;
const anomalies = data.anomalies || [];

const prompt = `You are an anomaly analyst for the SwjshAK autonomous trading system.

Analyze these detected anomalies and provide actionable insights:

TIMESTAMP: ${data.timestamp}
TOTAL ANOMALIES: ${data.anomalyCount}
CRITICAL: ${anomalies.filter(a => a.severity === 'critical').length}
HIGH: ${anomalies.filter(a => a.severity === 'high').length}

DETECTED ANOMALIES:
${anomalies.map((a, i) => `
${i + 1}. [${a.severity.toUpperCase()}] ${a.type}
   ${a.description}
   Current: ${typeof a.currentValue === 'number' ? a.currentValue.toFixed(2) : a.currentValue}
   Baseline: ${typeof a.baseline === 'number' ? a.baseline.toFixed(2) : a.baseline}
   Z-Score: ${a.zScore.toFixed(2)}
   ${a.affectedAgents ? 'Affected Agents: ' + a.affectedAgents.join(', ') : ''}
   ${a.affectedEndpoints ? 'Affected Endpoints: ' + a.affectedEndpoints.map(e => e.path).join(', ') : ''}
`).join('')}

METRICS SNAPSHOT:
- Trades in last hour: ${data.metricsSnapshot.recentHourTrades}
- Today's P&L: $${data.metricsSnapshot.todayPnL.toFixed(2)}
- Errors in last hour: ${data.metricsSnapshot.recentErrors}
- Current loss streak: ${data.metricsSnapshot.consecutiveLosses}

Your analysis should:
1. Identify the most likely ROOT CAUSE for each anomaly (or group related anomalies)
2. Determine if anomalies are CORRELATED (e.g., high latency causing errors)
3. Assess URGENCY (immediate action vs monitoring)
4. Suggest SPECIFIC remediation steps

Respond as JSON:
{
  "rootCauses": [
    {
      "cause": "brief description",
      "affectedAnomalies": ["type1", "type2"],
      "confidence": "high|medium|low",
      "evidence": "why you believe this"
    }
  ],
  "correlations": [
    {
      "anomalies": ["type1", "type2"],
      "relationship": "description of how they're related"
    }
  ],
  "urgency": "immediate|soon|monitor",
  "urgencyReason": "why this urgency level",
  "remediations": [
    {
      "action": "specific action",
      "target": "what to fix",
      "priority": 1,
      "automated": true|false
    }
  ],
  "summary": "2-3 sentence executive summary"
}`;

return { json: { prompt, anomalyData: data } };

const response = $json;
const inputData = $('Code: Build Claude Analysis Prompt').first().json;
const anomalyData = inputData.anomalyData;

let analysis;

try {
  const content = response.content?.[0]?.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : null;
} catch (e) {
  analysis = null;
}

// Fallback if parsing fails
if (!analysis) {
  analysis = {
    rootCauses: [{ cause: 'Analysis parsing failed', affectedAnomalies: anomalyData.anomalies.map(a => a.type), confidence: 'low' }],
    correlations: [],
    urgency: anomalyData.hasCritical ? 'immediate' : 'soon',
    urgencyReason: 'Defaulting based on anomaly severity',
    remediations: [{ action: 'Review anomalies manually', target: 'system', priority: 1, automated: false }],
    summary: `${anomalyData.anomalyCount} anomalies detected. Manual review recommended.`,
    _parsingFailed: true
  };
}

return {
  json: {
    ...analysis,
    originalAnomalies: anomalyData.anomalies,
    anomalyCount: anomalyData.anomalyCount,
    hasCritical: anomalyData.hasCritical,
    hasHigh: anomalyData.hasHigh,
    timestamp: anomalyData.timestamp,
    metricsSnapshot: anomalyData.metricsSnapshot
  }
};

