// Update rolling baselines with current metrics
// This is a simplified version - production would use more sophisticated EWMA
const anomalyData = $('Code: Calculate Z-Score Anomalies').first()?.json || {};
const metrics = anomalyData.metricsSnapshot || {};

// Only update baselines when no critical anomalies (to avoid poisoning baselines)
if (!anomalyData.hasCritical) {
  return {
    json: {
      shouldUpdate: true,
      newMetrics: {
        tradeFrequency: metrics.recentHourTrades,
        errorRate: metrics.recentErrors,
        timestamp: anomalyData.timestamp
      }
    }
  };
}

return {
  json: {
    shouldUpdate: false,
    reason: 'Critical anomaly detected - skipping baseline update'
  }
};

const error = $json;

return {
  json: {
    title: 'WF-OPS-02 Anomaly Detector Error',
    description: 'The anomaly detector workflow encountered an error.',
    color: 15158332,
    errorMessage: error.execution?.error?.message?.substring(0, 500) || 'Unknown error',
    failedNode: error.execution?.error?.node?.name || 'Unknown',
    executionId: error.execution?.id || 'Unknown',
    timestamp: new Date().toISOString()
  }
};
